  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text || ['null', 'undefined'].includes(text.toLowerCase())) return null;
  return text;
}
const input = $json || {};
const conversionOutboxId = cleanText(input.conversion_outbox_id || input.outbox_id || input.id);
const dispatchMode = cleanText(input.dispatch_mode) || 'inline';
const claimedAttempt = input.claimed_attempt === undefined || input.claimed_attempt === null
  ? null : Number(input.claimed_attempt);
if (!['inline', 'scheduled'].includes(dispatchMode)) throw new Error('invalid_dispatch_mode');
if (dispatchMode === 'scheduled' && (!conversionOutboxId || !Number.isInteger(claimedAttempt))) {
  throw new Error('scheduled_claim_context_required');
