return [{ json: { conversion_outbox_id: conversionOutboxId, dispatch_mode: dispatchMode,
  claimed_attempt: claimedAttempt, received_input: input } }];

/**
 * 04 v2 - Build Data Manager Request
 *
 * Troca o upload antigo da Google Ads API por Data Manager API:
 * POST https://datamanager.googleapis.com/v1/events:ingest
 *
 * Começa em validateOnly=true para validar sem aplicar a conversão.
 * Depois do teste OK, altere DEFAULT_VALIDATE_ONLY para false.
 */

const DEFAULT_VALIDATE_ONLY = false;
const DATA_MANAGER_ENDPOINT = 'https://datamanager.googleapis.com/v1/events:ingest';

function pick(...values) {
  return values.find(value => value !== undefined && value !== null && value !== '') || null;
}

function cleanText(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text || ['null', 'undefined', 'n/a', 'na', 'sem informação', 'sem informacao'].includes(text.toLowerCase())) return null;
  return text;
}

function parseMaybeJson(value, fallback = {}) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch (error) { return fallback; }
}

function normalizeKey(value) {
  const text = cleanText(value);
  if (!text) return null;
  return text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().replace(/\s+/g, '_').replace(/-/g, '_').toLowerCase();
}

function parseBoolean(value, defaultValue = null) {
  if (value === undefined || value === null || value === '') return defaultValue;
  if (typeof value === 'boolean') return value;
  const text = normalizeKey(value);
  if (['true', '1', 'yes', 'sim', 'enabled', 'ativo'].includes(text)) return true;
  if (['false', '0', 'no', 'nao', 'não', 'disabled', 'inativo'].includes(text)) return false;
  return defaultValue;
}

function parseMoney(value) {
  const cleaned = cleanText(value);
  if (!cleaned) return null;
  if (typeof value === 'number') return value;
  const text = String(cleaned).replace(/[R$\s]/g, '').replace(/\./g, '').replace(',', '.');
  const number = Number(text);
  return Number.isNaN(number) ? null : number;
}

function onlyDigits(value) {
  const text = cleanText(value);
  if (!text) return null;
  const digits = text.replace(/\D/g, '');
  return digits || null;
}

function normalizeCustomerId(value) {
  return onlyDigits(value);
}

function getConversionActionId(resourceNameOrId) {
  const text = cleanText(resourceNameOrId);
  if (!text) return null;
  const match = text.match(/conversionActions\/(\d+)$/);
  if (match) return match[1];
  return onlyDigits(text);
}

function toIsoTimestamp(value) {
  const text = cleanText(value);
  const date = text ? new Date(text) : new Date();
  if (Number.isNaN(date.getTime())) return new Date().toISOString();
  return date.toISOString();
}

function normalizeEmailForHash(value) {
  const text = cleanText(value);
  if (!text) return null;
  return text.toLowerCase();
}

function normalizePhoneE164(value, fallbackValue = null) {
  const source = cleanText(value) || cleanText(fallbackValue);
  if (!source) return null;
  const digits = source.replace(/\D/g, '');
  if (!digits) return null;
  if (source.trim().startsWith('+')) return `+${digits}`;
  if (digits.startsWith('55')) return `+${digits}`;
  if (digits.length === 10 || digits.length === 11) return `+55${digits}`;
  return `+${digits}`;
}

function rightRotate(value, amount) {
  return (value >>> amount) | (value << (32 - amount));
}

function sha256Hex(value) {
  const text = cleanText(value);
  if (!text) return null;

  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = 'length';
  let i;
  let j;
  const words = [];
  const asciiBitLength = text[lengthProperty] * 8;

  let hash = sha256Hex.h = sha256Hex.h || [];
  let k = sha256Hex.k = sha256Hex.k || [];
  let primeCounter = k[lengthProperty];
  const isComposite = {};

  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }

  let message = unescape(encodeURIComponent(text));
  message += '\x80';
  while (message[lengthProperty] % 64 - 56) message += '\x00';

  for (i = 0; i < message[lengthProperty]; i++) {
    j = message.charCodeAt(i);
    if (j >> 8) throw new Error('sha256_invalid_character');
    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }

  words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
  words[words[lengthProperty]] = asciiBitLength;

  for (j = 0; j < words[lengthProperty];) {
    const w = words.slice(j, j += 16);
    const oldHash = hash.slice(0);

    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const a = hash[0];
      const e = hash[4];
      const temp1 = hash[7]
        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
        + ((e & hash[5]) ^ ((~e) & hash[6]))
        + k[i]
        + (w[i] = (i < 16) ? w[i] : (
          w[i - 16]
          + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
          + w[i - 7]
          + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
        ) | 0);
      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));

      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
    }

    for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }

  let result = '';
  for (i = 0; i < 8; i++) {
    for (j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      result += ((b < 16) ? '0' : '') + b.toString(16);
    }
  }
  return result.toUpperCase();
}

const row = $('Get Single Google Outbox').first().json || {};
const clientConfig = parseMaybeJson(row.client_config, {});
const payload = parseMaybeJson(row.outbox_payload, {});
const userDataSource = payload.user_data_source || {};
const customData = payload.custom_data || {};
const attribution = payload.attribution || {};
const clickIdsPayload = payload.click_ids || {};
const settings = parseMaybeJson(clientConfig.google_data_manager_settings, {});

const eventCode = normalizeKey(row.event_code || payload.google_event_code || payload.event_code);
const googleEventName = cleanText(payload.google_event_name || payload.platform_event_name || row.google_event_name || row.meta_event_name || eventCode);

const conversionActionField = payload.google_config_hint?.conversion_action_field || (
  eventCode === 'lead' ? 'google_conversion_action_lead' :
  eventCode === 'agendado' ? 'google_conversion_action_agendado' :
  eventCode === 'ganho' ? 'google_conversion_action_ganho' : null
);

const conversionActionResource = cleanText(
  pick(
    payload.conversion_action,
    payload.google_conversion_action,
    conversionActionField ? clientConfig[conversionActionField] : null,
    eventCode === 'lead' ? clientConfig.google_conversion_action_lead : null,
    eventCode === 'agendado' ? clientConfig.google_conversion_action_agendado : null,
    eventCode === 'ganho' ? clientConfig.google_conversion_action_ganho : null
  )
);

const conversionActionId = getConversionActionId(conversionActionResource);
const customerId = normalizeCustomerId(pick(payload.customer_id, clientConfig.google_ads_customer_id));
const managerCustomerId = normalizeCustomerId(pick(payload.manager_customer_id, clientConfig.google_manager_customer_id));
const dispatchMethod = cleanText(clientConfig.google_ads_dispatch_method) || 'data_manager_api';
const dataManagerEnabled = parseBoolean(clientConfig.google_data_manager_enabled, true);
const validateOnly = parseBoolean(pick(payload.validate_only, settings.validate_only, settings.validateOnly), DEFAULT_VALIDATE_ONLY);

const emailNormalized = normalizeEmailForHash(pick(userDataSource.email, row.email));
const phoneNormalized = normalizePhoneE164(pick(userDataSource.phone_raw, row.phone_raw), pick(userDataSource.phone, row.phone));

const userIdentifiers = [];
if (emailNormalized) userIdentifiers.push({ emailAddress: sha256Hex(emailNormalized) });
if (phoneNormalized) userIdentifiers.push({ phoneNumber: sha256Hex(phoneNormalized) });

const gclid = cleanText(pick(clickIdsPayload.gclid, attribution.gclid, row.gclid));
const gbraid = cleanText(pick(clickIdsPayload.gbraid, attribution.gbraid, row.gbraid));
const wbraid = cleanText(pick(clickIdsPayload.wbraid, attribution.wbraid, row.wbraid));

const adIdentifiers = {};
if (gclid) adIdentifiers.gclid = gclid;
if (gbraid) adIdentifiers.gbraid = gbraid;
if (wbraid) adIdentifiers.wbraid = wbraid;

const value = parseMoney(pick(customData.value, row.valor_ganho)) ?? 0;
const currency = cleanText(pick(customData.currency, clientConfig.default_currency)) || 'BRL';
const timestamp = toIsoTimestamp(pick(row.event_datetime, row.received_at, row.outbox_created_at));
const transactionId = cleanText(payload.event_id) || `${row.outbox_id}:${eventCode || 'event'}`;

const validationErrors = [];
if (dispatchMethod !== 'data_manager_api') validationErrors.push(`google_dispatch_method_not_data_manager_api:${dispatchMethod}`);
if (!dataManagerEnabled) validationErrors.push('google_data_manager_disabled');
if (!customerId) validationErrors.push('missing_google_ads_customer_id');
if (!conversionActionId) validationErrors.push('missing_google_conversion_action_id');
if (!eventCode) validationErrors.push('missing_event_code');
if (!Object.keys(adIdentifiers).length && !userIdentifiers.length) validationErrors.push('missing_google_match_key');

if (validationErrors.length) {
  return [{
    json: {
      outbox_id: row.outbox_id,
    dispatch_mode: row.dispatch_mode,
    claimed_attempt: row.claimed_attempt,
      dispatch_mode: row.dispatch_mode,
      claimed_attempt: row.claimed_attempt,
      normalized_event_id: row.normalized_event_id,
      event_code: row.event_code,
      route: row.route,
      google_event_name: googleEventName,
      meta_event_name: row.meta_event_name,
      should_send_to_google: false,
      final_status: 'skipped',
      last_error: validationErrors.join(', '),
      google_response: {
        dispatcher: 'data_manager_api',
        validation_errors: validationErrors,
        outbox_payload: payload,
        client_config_preview: {
          google_ads_customer_id: customerId,
          google_manager_customer_id: managerCustomerId,
          google_ads_dispatch_method: dispatchMethod,
          google_data_manager_enabled: dataManagerEnabled,
          conversion_action_field: conversionActionField,
          conversion_action_resource: conversionActionResource,
          conversion_action_id: conversionActionId
        }
      }
    }
  }];
}

const destination = {
  operatingAccount: {
    accountType: 'GOOGLE_ADS',
    accountId: customerId
  },
  productDestinationId: conversionActionId
};

if (managerCustomerId) {
  destination.loginAccount = {
    accountType: 'GOOGLE_ADS',
    accountId: managerCustomerId
  };
}

const event = {
  transactionId,
  eventTimestamp: timestamp,
  eventSource: 'WEB',
  currency,
  conversionValue: value,
  conversionCount: 1,
  eventName: eventCode
};

if (Object.keys(adIdentifiers).length) event.adIdentifiers = adIdentifiers;
if (userIdentifiers.length) event.userData = { userIdentifiers };

const requestBody = {
  destinations: [destination],
  events: [event],
  consent: {
    adUserData: 'CONSENT_GRANTED',
    adPersonalization: 'CONSENT_GRANTED'
  },
  encoding: 'HEX',
  validateOnly
};

return [{
  json: {
    outbox_id: row.outbox_id,
    normalized_event_id: row.normalized_event_id,
    event_code: row.event_code,
    route: row.route,
    google_event_name: googleEventName,
    meta_event_name: row.meta_event_name,
    should_send_to_google: true,
    google_request: {
      url: DATA_MANAGER_ENDPOINT,
      headers: {
        'Content-Type': 'application/json'
      },
      headers_for_storage: {
        'Content-Type': 'application/json'
      },
      request_body: requestBody,
      api: 'data_manager_api',
      api_version: cleanText(clientConfig.google_data_manager_api_version) || 'v1',
      validate_only: validateOnly,
      customer_id: customerId,
      login_customer_id: managerCustomerId,
      conversion_action: conversionActionResource,
      conversion_action_id: conversionActionId,
      product_destination_id: conversionActionId,
      has_click_id: Object.keys(adIdentifiers).length > 0,
      has_user_identifiers: userIdentifiers.length > 0,
      match_keys: {
        gclid: Boolean(gclid),
        gbraid: Boolean(gbraid),
        wbraid: Boolean(wbraid),
        email: Boolean(emailNormalized),
        phone: Boolean(phoneNormalized)
      }
    }
  }
}];

/**
 * Finaliza a resposta da Data Manager API e também erros internos do HTTP node.
 *
 * Casos cobertos:
 * - HTTP 2xx: sent (ou skipped em validateOnly)
 * - HTTP 429/5xx: pending + retry
 * - HTTP 4xx da plataforma: failed
 * - OAuth/credencial, rede e falhas internas do node: pending + erro operacional registrado
 */
function cleanText(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text || ['null', 'undefined'].includes(text.toLowerCase())) return null;
  return text;
}

function pick(...values) {
  return values.find(value => value !== undefined && value !== null && value !== '') || null;
}

function parseMaybeJson(value) {
  if (value === undefined || value === null) return {};
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch (error) { return { raw_response: String(value) }; }
}

function serializeError(errorValue) {
  if (errorValue === undefined || errorValue === null) return null;
  if (typeof errorValue === 'object') {
    return {
      name: cleanText(errorValue.name),
      message: cleanText(errorValue.message),
      description: cleanText(errorValue.description),
      code: cleanText(errorValue.code),
      status: errorValue.status ?? errorValue.statusCode ?? null,
      cause: errorValue.cause ?? null,
      stack: cleanText(errorValue.stack)
    };
  }
  return { message: cleanText(errorValue) || String(errorValue) };
}

function classifyNodeError(message, errorObject = {}) {
  const text = [
    message,
    errorObject.name,
    errorObject.code,
    errorObject.description,
    errorObject.cause?.message
  ].filter(Boolean).join(' ').toLowerCase();

  const credentialPatterns = [
    'needs to be reconnected',
    'credential',
    'invalid_grant',
    'unauthorized_client',
    'access token',
    'refresh token',
    'oauth',
    'authorization grant',
    'token has been expired',
    'token has been revoked'
  ];

  const networkPatterns = [
    'timeout',
    'timed out',
    'econnreset',
    'econnrefused',
    'enotfound',
    'eai_again',
    'etimedout',
    'socket hang up',
    'network error',
    'fetch failed'
  ];

  if (credentialPatterns.some(pattern => text.includes(pattern))) return 'credential';
  if (networkPatterns.some(pattern => text.includes(pattern))) return 'network';
  return 'http_node';
}

const requestItem = $('Build Data Manager Request').first().json || {};
const http = $json || {};
const validateOnly = requestItem.google_request?.validate_only === true;

const requestContext = {
  request_body: requestItem.google_request?.request_body || null,
  headers: requestItem.google_request?.headers_for_storage || null,
  api_version: requestItem.google_request?.api_version || 'v1',
  validate_only: validateOnly,
  customer_id: requestItem.google_request?.customer_id || null,
  login_customer_id: requestItem.google_request?.login_customer_id || null,
  conversion_action: requestItem.google_request?.conversion_action || null,
  conversion_action_id: requestItem.google_request?.conversion_action_id || null,
  product_destination_id: requestItem.google_request?.product_destination_id || null,
  has_click_id: requestItem.google_request?.has_click_id || false,
  has_user_identifiers: requestItem.google_request?.has_user_identifiers || false,
  match_keys: requestItem.google_request?.match_keys || {}
};

// "Continue (using regular output)" devolve falhas do próprio node em http.error.
if (http.error) {
  const nodeError = serializeError(http.error) || {};
  const errorMessage = cleanText(
    pick(
      nodeError.message,
      http.message,
      nodeError.description,
      nodeError.cause?.message,
      'unknown_http_node_error'
    )
  );

  const errorClass = classifyNodeError(errorMessage, nodeError);
  const errorPrefix = errorClass === 'credential'
    ? 'credential_reconnect_required'
    : errorClass === 'network'
      ? 'network_error'
      : 'http_node_error';

  return [{
    json: {
      outbox_id: requestItem.outbox_id,
      dispatch_mode: requestItem.dispatch_mode,
      claimed_attempt: requestItem.claimed_attempt,
      normalized_event_id: requestItem.normalized_event_id,
      event_code: requestItem.event_code,
      route: requestItem.route,
      google_event_name: requestItem.google_event_name,
      meta_event_name: requestItem.meta_event_name,
      final_status: 'pending',
      error_class: errorClass,
      retryable: true,
      keep_pending_after_max_attempts: errorClass === 'credential',
      workflow_log_status: 'error',
      workflow_log_stage: errorClass === 'credential'
        ? 'credential_error_recorded'
        : 'dispatch_transport_error_recorded',
      last_error: `${errorPrefix}: ${errorMessage}`,
      google_response: {
        api: 'data_manager_api',
        error_class: errorClass,
        retryable: true,
        node_error: nodeError,
        ...requestContext
      }
    }
  }];
}

const statusCode = Number(
  pick(
    http.statusCode,
    http.status,
    http.response?.statusCode,
    http.response?.status,
    200
  )
);
const responseBody = parseMaybeJson(pick(http.body, http.data, http));
const hasApiError = Boolean(responseBody?.error);
const requestId = cleanText(responseBody?.requestId || responseBody?.request_id);

const baseResponse = {
  api: 'data_manager_api',
  http_status: statusCode,
  body: responseBody,
  request_id: requestId,
  ...requestContext
};

if (statusCode >= 200 && statusCode < 300 && !hasApiError) {
  if (validateOnly) {
    return [{
      json: {
        outbox_id: requestItem.outbox_id,
      dispatch_mode: requestItem.dispatch_mode,
      claimed_attempt: requestItem.claimed_attempt,
        dispatch_mode: requestItem.dispatch_mode,
        claimed_attempt: requestItem.claimed_attempt,
        normalized_event_id: requestItem.normalized_event_id,
        event_code: requestItem.event_code,
        route: requestItem.route,
        google_event_name: requestItem.google_event_name,
        meta_event_name: requestItem.meta_event_name,
        final_status: 'skipped',
        error_class: null,
        retryable: false,
        workflow_log_status: 'success',
        workflow_log_stage: 'dispatch_skipped',
        last_error: 'validate_only_ok_not_sent',
        google_response: {
          ...baseResponse,
          validation_status: 'ok_not_sent'
        }
      }
    }];
  }

  return [{
    json: {
      outbox_id: requestItem.outbox_id,
      dispatch_mode: requestItem.dispatch_mode,
      claimed_attempt: requestItem.claimed_attempt,
      normalized_event_id: requestItem.normalized_event_id,
      event_code: requestItem.event_code,
      route: requestItem.route,
      google_event_name: requestItem.google_event_name,
      meta_event_name: requestItem.meta_event_name,
      final_status: 'sent',
      error_class: null,
      retryable: false,
      workflow_log_status: 'success',
      workflow_log_stage: 'dispatch_sent',
      last_error: null,
      google_response: baseResponse
    }
  }];
}

const apiErrorMessage = cleanText(
  pick(
    responseBody?.error?.message,
    responseBody?.error?.status,
    responseBody?.raw_response,
    `http_${statusCode}`
  )
);
const retryable = statusCode === 429 || statusCode >= 500;

return [{
  json: {
    outbox_id: requestItem.outbox_id,
    normalized_event_id: requestItem.normalized_event_id,
    event_code: requestItem.event_code,
    route: requestItem.route,
    google_event_name: requestItem.google_event_name,
    meta_event_name: requestItem.meta_event_name,
    final_status: retryable ? 'pending' : 'failed',
    error_class: retryable ? 'api_transient' : 'api_rejection',
    retryable,
    keep_pending_after_max_attempts: false,
    workflow_log_status: retryable ? 'error' : 'success',
    workflow_log_stage: retryable
      ? 'dispatch_retry_scheduled'
      : 'dispatch_failed_recorded',
    last_error: `data_manager_api_error: ${apiErrorMessage}`,
    google_response: {
      ...baseResponse,
      error_class: retryable ? 'api_transient' : 'api_rejection',
      error_message: apiErrorMessage,
      retryable
    }
  }
}];
